import { sveltekit } from "@sveltejs/kit/vite";
import tailwindcss from "@tailwindcss/vite";
import { readFileSync } from "node:fs";
// R10-60: the signed-in app's shell (the modules every screen needs: the Svelte runtime, the router, the menus, the icons, the layout) is ONE script instead of ~80 small ones. On a phone over a
// slow link each request costs a round trip, so first paint waited on the queue, not on the bytes. The list is generated by scripts/shell-modules.mjs from what a real signed-in page loads;
// a module that is no longer on the list simply goes back to normal chunking (slower, never broken). Pages keep their own code in their own scripts.
// SHELL_MODULES_REGEN=1 turns the grouping off, so a build shows what each screen really imports (see scripts/shell-modules.mjs)
const shell = new Set(process.env.SHELL_MODULES_REGEN ? [] : JSON.parse(readFileSync(new URL("./shell-modules.json", import.meta.url), "utf8")));
const norm = (id) => { const m = /(node_modules\/.*|src\/.*)$/.exec(id.replace(/\\/g, "/").split("?")[0]); return m ? m[1] : id; };
export default { plugins: [tailwindcss(), sveltekit()], server: { port: 5180 }, build: { rolldownOptions: { output: { codeSplitting: { groups: [{ name: "app-shell", test: (id) => shell.has(norm(id)), minSize: 0 }] } } } } };
